create table materials (id uuid primary key, project_id uuid not null references reporting_projects(id), owner_id uuid not null references app_users(id), material_type varchar(16) not null, material_created_time timestamp with time zone not null, current_version_id uuid not null);
create table material_versions (id uuid primary key, material_id uuid not null references materials(id), version_number integer not null, created_by uuid not null references app_users(id), version_created_time timestamp with time zone not null, title varchar(240) not null, event_time timestamp with time zone null, location varchar(240) null, text_body text null, constraint uq_material_version unique (material_id, version_number));
create table material_version_tags (version_id uuid not null references material_versions(id), position integer not null, tag_value varchar(80) not null, primary key (version_id, position));
create table idempotency_records (id uuid primary key, user_id uuid not null references app_users(id), operation_name varchar(40) not null, idempotency_key varchar(255) not null, payload_fingerprint varchar(128) not null, material_id uuid not null references materials(id), version_number integer not null, created_at timestamp with time zone not null, constraint uq_idempotency_user_operation_key unique (user_id, operation_name, idempotency_key));
